// GENERATED by scripts/build-help.mjs from content/help/. Do not edit by hand.
export const STAFF_GUIDE = "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\"><title>Staff guide</title><meta name=\"description\" content=\"How to run the platform day to day. The examples follow Acme Home Sp. z o.o. and one delivery, from the customer's booking to the warehouse shelf. Names and numbers are invented.\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100,800&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap\" rel=\"stylesheet\"><style>/* Layout: a two-guide manual. Header with the audience switch, a sticky contents column, and long-form sections with worked examples. */\n  :root {\n    --bg: #F5F4F1; --surface: #FFFFFF; --fg: #14161A; --muted: #5C6068; --line: rgba(20,22,26,.13);\n    --accent: #B97A12; --accent-soft: rgba(227,154,43,.16); --ink: #0B0C0E; --on-ink: #F5F4F1;\n    --ok: #2F7D55; --ok-soft: rgba(47,125,85,.12); --warn: #8A5A10; --bad: #B3392C; --bad-soft: rgba(179,57,44,.1);\n    --ex-bg: #FBF3E3; --ex-line: #E39A2B;\n    --display: 'Archivo', 'Arial Narrow', Arial, sans-serif; --body: 'IBM Plex Sans', system-ui, sans-serif; --mono: 'IBM Plex Mono', ui-monospace, Menlo, monospace;\n  }\n  * { box-sizing: border-box; }\n  html { scroll-behavior: smooth; scroll-padding-top: 84px; }\n  body { margin: 0; padding-inline: 16px; background: var(--bg); color: var(--fg); font: 16px/1.65 var(--body); -webkit-font-smoothing: antialiased; }\n  a { color: var(--accent); }\n  .wrap { max-width: 1180px; margin-inline: auto; }\n\n  header.top { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; margin-inline: -16px; padding: 12px 16px; background: var(--ink); color: var(--on-ink); display: flex; flex-wrap: wrap; align-items: center; gap: 10px 20px; }\n  .brand { font-family: var(--display); font-variation-settings: 'wdth' 118; font-weight: 800; font-size: 22px; letter-spacing: .02em; }\n  .brand small { font: 500 11px var(--mono); letter-spacing: .16em; text-transform: uppercase; color: var(--accent); margin-left: 10px; }\n  .switch { display: flex; gap: 4px; margin-left: auto; padding: 3px; border: 1px solid rgba(245,244,241,.25); border-radius: 4px; }\n  .switch a { padding: 8px 14px; border-radius: 3px; color: rgba(245,244,241,.75); text-decoration: none; font: 500 12px var(--mono); letter-spacing: .1em; text-transform: uppercase; }\n  .switch a[aria-current=\"true\"] { background: var(--on-ink); color: var(--ink); }\n\n  .hero { padding-block: 40px 20px; }\n  .hero h1 { font-family: var(--display); font-variation-settings: 'wdth' 108; font-weight: 800; font-size: clamp(34px, 6vw, 60px); line-height: 1; letter-spacing: -.025em; margin: 0 0 14px; text-wrap: balance; }\n  .hero p { max-width: 64ch; color: var(--muted); margin: 0; font-size: 17px; }\n  .cast { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr)); gap: 12px; margin-top: 26px; }\n  .cast div { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 14px 16px; font-size: 14px; }\n  .cast b { display: block; font: 500 11px var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--accent); margin-bottom: 4px; }\n\n  .cols { display: grid; grid-template-columns: 250px minmax(0, 1fr); gap: 40px; padding-block: 24px 80px; align-items: start; }\n  nav.toc { position: sticky; top: calc(76px + env(safe-area-inset-top, 0px)); max-height: calc(100vh - 100px); overflow-y: auto; font-size: 14px; }\n  nav.toc h2 { font: 500 11px var(--mono); letter-spacing: .16em; text-transform: uppercase; color: var(--muted); margin: 0 0 10px; }\n  nav.toc a { display: block; padding: 6px 10px; border-left: 2px solid var(--line); color: var(--muted); text-decoration: none; }\n  nav.toc a:hover, nav.toc a.on { color: var(--fg); border-left-color: var(--accent); }\n  @media (max-width: 900px) { .cols { grid-template-columns: minmax(0, 1fr); gap: 8px; } nav.toc { position: static; max-height: none; } nav.toc .list { display: none; } nav.toc[data-open=\"true\"] .list { display: block; } .tocbtn { display: inline-block !important; } }\n  .tocbtn { display: none; font: 500 12px var(--mono); letter-spacing: .1em; text-transform: uppercase; background: var(--surface); color: var(--fg); border: 1px solid var(--line); border-radius: 4px; padding: 10px 14px; cursor: pointer; margin-bottom: 8px; }\n\n  article { min-width: 0; }\n  section { padding-block: 8px 28px; border-top: 1px solid var(--line); margin-top: 28px; }\n  section:first-of-type { border-top: 0; margin-top: 0; }\n  h2 { font-family: var(--display); font-variation-settings: 'wdth' 106; font-weight: 800; font-size: clamp(26px, 3.4vw, 36px); line-height: 1.08; letter-spacing: -.02em; margin: 18px 0 10px; text-wrap: balance; }\n  h3 { font-family: var(--display); font-weight: 800; font-size: 19px; letter-spacing: -.01em; margin: 26px 0 6px; }\n  p, li { max-width: 72ch; }\n  ol, ul { padding-left: 22px; } li { margin: 5px 0; }\n  .lead { color: var(--muted); font-size: 17px; }\n  code, .kbd { font-family: var(--mono); font-size: .88em; background: var(--accent-soft); padding: 1px 6px; border-radius: 3px; word-break: break-word; }\n\n  .ex { background: var(--ex-bg); border: 1px solid var(--line); border-left: 4px solid var(--ex-line); border-radius: 4px; padding: 14px 18px; margin: 16px 0; }\n  .ex > b:first-child, .note > b:first-child, .rule > b:first-child { display: block; font: 500 11px var(--mono); letter-spacing: .16em; text-transform: uppercase; margin-bottom: 6px; color: var(--accent); }\n  .note { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 12px 18px; margin: 16px 0; font-size: 15px; }\n  .note > b:first-child { color: var(--muted); }\n  .rule { background: var(--bad-soft); border: 1px solid var(--line); border-radius: 4px; padding: 12px 18px; margin: 16px 0; font-size: 15px; }\n  .rule > b:first-child { color: var(--bad); }\n  .ex p, .note p, .rule p { margin: 6px 0; }\n  .steps { counter-reset: s; list-style: none; padding: 0; }\n  .steps > li { counter-increment: s; position: relative; padding: 4px 0 4px 44px; margin: 10px 0; }\n  .steps > li::before { content: counter(s); position: absolute; left: 0; top: 2px; width: 28px; height: 28px; border-radius: 50%; background: var(--ink); color: var(--on-ink); font: 500 13px/28px var(--mono); text-align: center; }\n  .tw { overflow-x: auto; margin: 14px 0; border: 1px solid var(--line); border-radius: 4px; background: var(--surface); }\n  table { border-collapse: collapse; width: 100%; font-size: 14px; min-width: 480px; }\n  th { text-align: left; font: 500 11px var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); padding: 10px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; }\n  td { padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; } tr:last-child td { border-bottom: 0; }\n  td.n, th.n { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\n  .y { color: var(--ok); font-weight: 600; } .no { color: var(--muted); } .ro { color: var(--warn); }\n  .pill { display: inline-block; font: 500 11px var(--mono); letter-spacing: .06em; padding: 2px 8px; border-radius: 10px; background: var(--accent-soft); color: var(--fg); white-space: nowrap; }\n  .pill.ok { background: var(--ok-soft); color: var(--ok); } .pill.bad { background: var(--bad-soft); color: var(--bad); }\n  .ui { font-weight: 600; }\n  footer.end { border-top: 1px solid var(--line); padding-block: 24px 48px; color: var(--muted); font-size: 14px; }\n  [hidden] { display: none !important; }\n  @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }\n\n  body { padding-inline: 0; }\n  .wrap { padding-inline: 16px; }\n  header.top { margin-inline: 0; padding-inline: max(16px, calc((100vw - 1180px) / 2 + 16px)); }\n  .sitenav { margin-left: auto; display: flex; flex-wrap: wrap; gap: 6px 18px; }\n  .sitenav a { color: rgba(245,244,241,.8); text-decoration: none; font: 500 12px var(--mono); letter-spacing: .1em; text-transform: uppercase; }\n  .sitenav a:hover { color: var(--on-ink); }\n  a.brand { color: var(--on-ink); text-decoration: none; }\n  .legalline { border-top: 1px solid var(--line); padding-block: 22px 44px; color: var(--muted); font-size: 13px; }\n  .legalline a { margin-right: 16px; }\n</style></head><body><div class=\"wrap\"><div class=\"hero\" style=\"padding-block:24px 8px\"><h1 style=\"font-size:clamp(28px,4vw,42px)\">Staff guide</h1><p>How to run the platform day to day. The examples follow Acme Home Sp. z o.o. and one delivery, from the customer's booking to the warehouse shelf. Names and numbers are invented.</p></div><div class=\"cols\"><nav class=\"toc\" id=\"toc\" data-open=\"false\" aria-label=\"Contents\"><button class=\"tocbtn\" id=\"tocbtn\" type=\"button\">Contents</button><div class=\"list\"><h2 id=\"tochead\">Staff guide</h2><div id=\"toclinks\"></div></div></nav><article><section id=\"s-roles\">\n  <h2>1. Roles and signing in</h2>\n  <p class=\"lead\">The admin panel lives at <code>2ace.pl/admin</code>. What you see depends on your role. The database enforces the same limits, so hiding a button is never the only protection.</p>\n  <div class=\"tw\"><table>\n    <tr><th>Area</th><th>Admin</th><th>Support</th><th>Warehouse</th></tr>\n    <tr><td>Two-step code at sign-in</td><td class=\"y\">Required</td><td class=\"y\">Required</td><td class=\"no\">Not required</td></tr>\n    <tr><td>Overview</td><td class=\"y\">All cards</td><td class=\"y\">All cards</td><td class=\"y\">Warehouse cards</td></tr>\n    <tr><td>Customers (open with a reason)</td><td class=\"y\">Yes</td><td class=\"y\">Yes</td><td class=\"no\">No</td></tr>\n    <tr><td>Change a customer's status</td><td class=\"y\">Yes</td><td class=\"no\">No</td><td class=\"no\">No</td></tr>\n    <tr><td>Customer invoices (view, email to owner)</td><td class=\"y\">Yes</td><td class=\"y\">Yes</td><td class=\"no\">No</td></tr>\n    <tr><td>Requests inbox</td><td class=\"y\">Yes</td><td class=\"y\">Yes</td><td class=\"no\">No</td></tr>\n    <tr><td>Domain queue</td><td class=\"y\">Yes</td><td class=\"y\">Yes</td><td class=\"no\">No</td></tr>\n    <tr><td>Staff management</td><td class=\"y\">Yes</td><td class=\"no\">No</td><td class=\"no\">No</td></tr>\n    <tr><td>Audit log</td><td class=\"y\">Yes</td><td class=\"y\">Yes</td><td class=\"no\">No</td></tr>\n    <tr><td>Approvals (decide)</td><td class=\"y\">Yes</td><td class=\"ro\">Read only</td><td class=\"y\">Yes</td></tr>\n    <tr><td>Inbound, receiving, discrepancies</td><td class=\"y\">Yes</td><td class=\"ro\">Read only</td><td class=\"y\">Yes</td></tr>\n    <tr><td>Stock: move, adjust</td><td class=\"y\">Yes, any size</td><td class=\"ro\">Read only</td><td class=\"y\">Yes, up to 20 units</td></tr>\n    <tr><td>Products and photos</td><td class=\"y\">Yes</td><td class=\"ro\">Read only</td><td class=\"y\">Yes</td></tr>\n    <tr><td>Locations and labels</td><td class=\"y\">Yes</td><td class=\"no\">No</td><td class=\"y\">Yes</td></tr>\n    <tr><td>Scan app (<code>/scan</code>)</td><td class=\"y\">Yes</td><td class=\"no\">No</td><td class=\"y\">Yes</td></tr>\n  </table></div>\n  <h3>First sign-in</h3>\n  <ol class=\"steps\">\n    <li>An admin invites you from <span class=\"ui\">Staff</span>. You get an email with a link.</li>\n    <li>Click the link and choose a password (8 characters or more).</li>\n    <li>Admin and Support accounts then set up a second factor: scan the QR code with an authenticator app such as Google Authenticator or 1Password, type the 6-digit code, and you are in.</li>\n    <li>From then on, signing in asks for your password and a fresh 6-digit code.</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>You invite <code>marta@2ace.pl</code> as Warehouse. She sets her password and goes straight to the panel with no code. You invite <code>piotr@2ace.pl</code> as Support. After his password he scans the QR code and from then on types a code at each sign-in.</p></div>\n  <div class=\"note\"><b>Good to know</b><p>If someone is deactivated, their access stops at once. A role change takes effect at their next request.</p></div>\n</section>\n\n<section id=\"s-home\">\n  <h2>2. The overview</h2>\n  <p>The first screen is a set of cards that tell you what needs attention. A highlighted card means there is work.</p>\n  <div class=\"tw\"><table>\n    <tr><th>Card</th><th>Click it to</th></tr>\n    <tr><td>New requests, Open requests</td><td>Open the requests inbox.</td></tr>\n    <tr><td>Domains to register</td><td>Open the domain queue.</td></tr>\n    <tr><td>Customers past due</td><td>Open customers, to chase payment.</td></tr>\n    <tr><td>Active customers</td><td>See who is live.</td></tr>\n    <tr><td>Changes to approve</td><td>Open Approvals.</td></tr>\n    <tr><td>Deliveries expected, Being received</td><td>Open Inbound.</td></tr>\n    <tr><td>Units to put away</td><td>Open Stock, To put away.</td></tr>\n    <tr><td>Open discrepancies</td><td>Open Discrepancies.</td></tr>\n  </table></div>\n  <div class=\"ex\"><b>Example: your morning</b><p>The overview shows 2 new requests, 1 domain to register, 1 change to approve and 12 units to put away. You work down the cards in that order.</p></div>\n</section>\n\n<section id=\"s-customers\">\n  <h2>3. Customers</h2>\n  <p class=\"lead\">A list of every company with its owner, plan, status, domain and open requests. Search by company, owner, email or domain, and filter by status.</p>\n  <h3>Open a customer</h3>\n  <p>Opening a customer needs a reason. You choose one (Support request, Billing check, Domain order, Onboarding help, Data correction or Other), add details, and the system records who opened which company and why. You are asked once per customer per browser session.</p>\n  <div class=\"ex\"><b>Example</b><p>Anna writes that she never got her invoice. Piotr opens Acme Home, chooses <i>Billing check</i>, and the customer page loads.</p></div>\n  <h3>What the customer page shows</h3>\n  <ul>\n    <li><b>Company</b>: country, tax ID, address, voivodeship, phone, Stripe customer id, join date.</li>\n    <li><b>People</b>: members and their roles.</li>\n    <li><b>Plan</b>: the current plan, monthly and one-time amounts, and history of earlier plans.</li>\n    <li><b>Subscription</b>: Stripe subscription id, status and renewal date.</li>\n    <li><b>Invoices</b>: loaded live from Stripe.</li>\n    <li><b>Signed agreements</b>: who signed, which version, from which IP and when. Domain customers also have a \"hostinger-domain-registration\" row. Keep this evidence at least 3 years, as Hostinger requires.</li>\n    <li><b>Domain orders</b> and <b>Requests</b> for that company.</li>\n  </ul>\n  <h3>Invoices and resending</h3>\n  <ol class=\"steps\">\n    <li>On the customer page find the <span class=\"ui\">Invoices</span> card.</li>\n    <li>Use <span class=\"ui\">View</span> for the customer's invoice page, <span class=\"ui\">Stripe</span> to open it in your Stripe dashboard, or <span class=\"ui\">Email to owner</span> to send the invoice link to the company owner.</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>Piotr clicks <span class=\"ui\">Email to owner</span> next to invoice INV-0007. A toast says \"Sent to anna@acmehome.pl\", and the audit log records it.</p></div>\n  <h3>Change a customer's status (admin only)</h3>\n  <p>Click <span class=\"ui\">Change status</span>, choose pending, active, past_due or canceled, and write a reason. This only changes the label in our system. It does not touch Stripe or the subscription.</p>\n  <div class=\"ex\"><b>Example</b><p>A test account was marked active by mistake. You set it to <i>pending</i> with the reason \"Test account, never paid\".</p></div>\n</section>\n\n<section id=\"s-requests\">\n  <h2>4. Requests inbox</h2>\n  <p class=\"lead\">Every message from the website contact form or a customer's Contact us button becomes a request with a thread.</p>\n  <div class=\"tw\"><table>\n    <tr><th>Status</th><th>Meaning</th></tr>\n    <tr><td><span class=\"pill\">new</span></td><td>Nobody has handled it.</td></tr>\n    <tr><td><span class=\"pill\">open</span></td><td>Being worked on, or the customer replied.</td></tr>\n    <tr><td><span class=\"pill\">waiting</span></td><td>We replied and are waiting for the customer.</td></tr>\n    <tr><td><span class=\"pill ok\">resolved</span></td><td>Done.</td></tr>\n  </table></div>\n  <h3>Handle a request</h3>\n  <ol class=\"steps\">\n    <li>Open the request. Set the priority (low, normal, high) and assign it to a team member. They get an email with a link.</li>\n    <li>Type a message and choose <span class=\"ui\">Reply</span> to email the customer, <span class=\"ui\">Note</span> to leave an internal comment the customer never sees, or <span class=\"ui\">Log incoming</span> to paste in something the customer wrote by email.</li>\n    <li>Replying sets the status to waiting. When it is dealt with, set it to resolved.</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>Request \"Import and customs quote\" from Acme, priority high. Piotr assigns it to himself, adds the note <i>Ask Kasia for sea freight rates</i> (internal), then replies: <i>Hi Anna, a 20 ft container from Ningbo to Gdansk costs about… Which Incoterm do you use?</i> The status becomes waiting. When Anna answers by email, Piotr pastes her reply with <span class=\"ui\">Log incoming</span> and the status returns to open.</p></div>\n  <div class=\"note\"><b>Good to know</b><p>Replies come from <code>hello@2ace.pl</code>, and the customer can answer to the same address. Customer change requests do not come here: they go to Approvals.</p></div>\n</section>\n\n<section id=\"s-domains\">\n  <h2>5. Domain queue</h2>\n  <p class=\"lead\">Each .pl domain a customer orders (included with a storefront, or paid 99 zł) lands here. By default you register it by hand. Automatic registration through Hostinger is off until you decide to switch it on.</p>\n  <div class=\"tw\"><table>\n    <tr><th>Status</th><th>Meaning</th></tr>\n    <tr><td><span class=\"pill\">pending</span></td><td>Needs registering.</td></tr>\n    <tr><td><span class=\"pill ok\">registered</span></td><td>Done. The customer was emailed once.</td></tr>\n    <tr><td><span class=\"pill bad\">failed</span></td><td>Registration did not work. Add a note.</td></tr>\n    <tr><td><span class=\"pill\">cancelled</span></td><td>Will not be registered, for example a refund.</td></tr>\n  </table></div>\n  <h3>Register a domain by hand</h3>\n  <ol class=\"steps\">\n    <li>Open the order. It shows the domain and the registrant details (company, tax ID, address, owner email), each with a <span class=\"ui\">Copy</span> button.</li>\n    <li>In your Hostinger account, register the domain in the <b>customer's company name</b>, copying the details from the page.</li>\n    <li>Back in the panel, paste Hostinger's order reference into the order and click <span class=\"ui\">Mark registered</span>. The customer gets the \"Your domain is registered\" email.</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>Order: <code>acmehome-sklep.pl</code>, pending. Piotr copies the company name and tax ID, registers it at Hostinger, pastes reference <code>HST-88231</code>, and clicks <span class=\"ui\">Mark registered</span>. Anna receives \"Your domain acmehome-sklep.pl is registered\".</p></div>\n  <h3>If it does not work</h3>\n  <p>Use <span class=\"ui\">Mark failed</span> with a note (for example \"Registry rejected the tax ID format\") or <span class=\"ui\">Cancel</span>. If automatic registration is on, <span class=\"ui\">Retry auto-register</span> tries again and tells you the result.</p>\n  <div class=\"note\"><b>Good to know</b><p>The customer accepted Hostinger's agreement before ordering. You can see that on their customer page under Signed agreements.</p></div>\n</section>\n\n<section id=\"s-staff\">\n  <h2>6. Staff management</h2>\n  <p>Admins only. The screen lists every staff member with role and status.</p>\n  <ol class=\"steps\">\n    <li>Click <span class=\"ui\">Invite</span>, enter an email and choose a role (admin, support or warehouse).</li>\n    <li>To change a role or switch someone off, use the buttons on their row.</li>\n  </ol>\n  <div class=\"rule\"><b>Rules</b><p>You cannot change your own role or deactivate yourself. There must always be at least one active admin.</p></div>\n  <div class=\"ex\"><b>Example</b><p>Marta changes from warehouse to admin because she covers for you. You open Staff, change her role, and the change is in the audit log as <code>staff.update</code>.</p></div>\n</section>\n\n<section id=\"s-audit\">\n  <h2>7. Audit log</h2>\n  <p class=\"lead\">A permanent record of who did what, when and why. Entries cannot be edited or deleted, even by an admin.</p>\n  <p>It records, among others: opening a customer, status changes, staff changes, domain updates, request replies, locations, products, deliveries, stock moves and adjustments, discrepancies, approvals, photos and invoice emails. Each entry has the person, their role, the action, the item, the company and the reason. You can filter the list.</p>\n  <div class=\"ex\"><b>Example</b><p>A customer asks \"who changed my delivery?\". You filter by Acme and see: <i>change.request</i> by Anna (customer), then <i>change.approve</i> by Marta (warehouse) and <i>inbound.update</i>, with times.</p></div>\n</section>\n\n<section id=\"s-setup\">\n  <h2>8. Set up the warehouse</h2>\n  <p class=\"lead\">Do this once. A location is a labelled place in the warehouse. Its code is what the barcode label says.</p>\n  <div class=\"tw\"><table>\n    <tr><th>Type</th><th>Use</th><th>Shared or dedicated</th></tr>\n    <tr><td>receiving</td><td>Where goods land before they are put away.</td><td>Shared by all customers</td></tr>\n    <tr><td>quarantine</td><td>Damaged goods or goods on hold.</td><td>Shared</td></tr>\n    <tr><td>bin</td><td>A shelf bin for stock.</td><td>Dedicated to one customer</td></tr>\n    <tr><td>pallet</td><td>A pallet slot for stock.</td><td>Dedicated to one customer</td></tr>\n    <tr><td>pack, returns, shipping</td><td>Stations for later order handling.</td><td>Shared</td></tr>\n  </table></div>\n  <ol class=\"steps\">\n    <li>Open <span class=\"ui\">Locations</span>. Click <span class=\"ui\">New location</span>, code <code>R1</code>, type <code>receiving</code>.</li>\n    <li>Create <code>Q1</code>, type <code>quarantine</code>.</li>\n    <li>Click <span class=\"ui\">Create many</span>: starts with <code>A-01-</code>, from 1 to 20, type <code>bin</code>. You get A-01-01 to A-01-20 in one go.</li>\n    <li>Assign a bin: click <span class=\"ui\">Assign</span> on A-01-01 and choose the customer. The Customer column now shows the company.</li>\n    <li>Tick the locations you want and click <span class=\"ui\">Print labels</span> (allow pop-ups). Print the page and stick the barcodes on the shelves.</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>Acme's plan includes 12 pallets. You create <code>PAL-01</code> to <code>PAL-12</code> as pallet locations and assign each to Acme Home. Storage is billed from these assignments.</p></div>\n  <div class=\"rule\"><b>Rules</b>\n    <p>A bin or pallet belongs to one customer at a time, and the database refuses to put another company's stock in it.</p>\n    <p>A location holding stock cannot be released, reassigned or switched off. Move the stock first.</p>\n    <p><span class=\"ui\">Edit</span> changes the note. The code cannot change, because it is printed on labels. <span class=\"ui\">Delete location</span> works only for a location never used. Otherwise use <span class=\"ui\">Switch off</span>.</p>\n  </div>\n</section>\n\n<section id=\"s-inbound\">\n  <h2>9. Receive a delivery</h2>\n  <p class=\"lead\">Follow one delivery from the dock to the shelf. The same steps work on the phone scan page.</p>\n  <h3>Before the truck arrives</h3>\n  <p>The <span class=\"ui\">Inbound</span> list shows deliveries that are expected, with customer, date, carrier and units. You can also book one for a customer with <span class=\"ui\">Book a delivery</span>: choose the customer, then add products and units. If the customer has no products, the dialog says so and offers <span class=\"ui\">Go to Products</span>.</p>\n  <h3>Receive the goods</h3>\n  <ol class=\"steps\">\n    <li>Open the delivery. Under <span class=\"ui\">Receive goods</span> choose the product, the quantity and the condition: <span class=\"ui\">Good</span> or <span class=\"ui\">Damaged</span>.</li>\n    <li>Good goods go to the receiving area. Damaged goods go to quarantine. For damaged goods, attach photos (a camera button appears on a phone) and add a note.</li>\n    <li>Click <span class=\"ui\">Receive</span>. Repeat for every product and condition. The delivery becomes <span class=\"pill\">Being received</span>.</li>\n    <li>If a product arrives that was not booked, it is accepted but flagged \"unexpected\".</li>\n    <li>When everything is counted, click <span class=\"ui\">Close receiving</span>. Differences become discrepancies, and the customer and the team inbox are emailed once.</li>\n  </ol>\n  <div class=\"ex\"><b>Example: delivery IN-000012</b>\n    <p>Booked: MUG-BLUE × 600, MUG-RED × 400. Marta receives MUG-BLUE: 590 Good, then 10 Damaged with two photos and the note \"cracked in transit\". She receives MUG-RED: 400 Good. She clicks <span class=\"ui\">Close receiving</span>.</p>\n    <p>The result is two discrepancies: <i>short</i> for MUG-BLUE (590 of 600 good) and <i>damaged</i> for MUG-BLUE (10). Anna gets an email listing both, with links to the photos.</p>\n  </div>\n  <h3>Resolve discrepancies</h3>\n  <p>Open <span class=\"ui\">Discrepancies</span>. Each open item shows the delivery, customer, product, the issue and booked versus received. Click <span class=\"ui\">Resolve</span> and write what was decided.</p>\n  <div class=\"ex\"><b>Example</b><p>For the short item Marta writes \"Supplier confirmed 10 units never shipped, customer informed\". For the damaged item: \"Customer will claim from carrier. Kept in quarantine until they decide.\"</p></div>\n  <h3>Fix a mistake before anything arrives</h3>\n  <p>While a delivery is still <span class=\"pill\">Booked</span> and nothing is received, staff can <span class=\"ui\">Edit</span> it directly (date, carrier, tracking, products and units, with a remove button on each line), <span class=\"ui\">Delete</span> it, or <span class=\"ui\">Cancel delivery</span>. Once goods are received it can no longer be edited or deleted.</p>\n</section>\n\n<section id=\"s-stock\">\n  <h2>10. Put away, count and adjust stock</h2>\n  <p class=\"lead\">The Stock screen has three tabs: <span class=\"ui\">To put away</span>, <span class=\"ui\">All stock</span> and <span class=\"ui\">Ledger</span>.</p>\n  <h3>Put goods away</h3>\n  <ol class=\"steps\">\n    <li>Open <span class=\"ui\">Stock → To put away</span>. It lists goods waiting in the receiving area, with a thumbnail of each product.</li>\n    <li>Click <span class=\"ui\">Move</span> on a row. Choose the destination (the customer's own bins, plus pack, returns and quarantine areas) and the quantity.</li>\n    <li>Click <span class=\"ui\">Move</span>. The stock leaves the receiving area and appears in the bin.</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>Marta moves 590 MUG-BLUE and 400 MUG-RED to bin <code>A-01-01</code>, which is assigned to Acme. Both rows leave the queue. The Locations screen now shows 990 units in A-01-01. The 10 damaged units stay in quarantine <code>Q1</code> until Acme decides what to do.</p></div>\n  <div class=\"rule\"><b>Rules</b><p>You can only move stock into a bin assigned to that customer. You cannot move more than is free, and you cannot move stock back into the receiving area.</p></div>\n  <h3>Adjust a count</h3>\n  <p>When a physical count differs from the system, post the difference. On <span class=\"ui\">All stock</span> click <span class=\"ui\">Adjust</span> on the row, enter the <b>change</b> (not the new total) and a reason.</p>\n  <div class=\"ex\"><b>Example</b><p>Marta counts 588 MUG-BLUE in A-01-01 but the system says 590. She enters change <code>-2</code>, reason \"Cycle count: two broken, found in bin\". The ledger gets one line: -2, adjust.</p></div>\n  <div class=\"rule\"><b>Rules</b><p>A reason is required. Changes above 20 units need an admin. An adjustment cannot make stock negative or take away units reserved for orders.</p></div>\n  <h3>The ledger</h3>\n  <p>Every change in stock is one line: time, customer, product, location, +/- quantity, reason (receive, putaway, adjust) and note. Lines are never edited or deleted. If a number looks wrong, read the ledger from the bottom up and you will find exactly where it changed. Repeated clicks or scans cannot post the same movement twice.</p>\n</section>\n\n<section id=\"s-products\">\n  <h2>11. Products and photos (staff)</h2>\n  <p>Open <span class=\"ui\">Products</span> to see every customer's catalogue, with thumbnails, barcodes, on hand, unplaced and incoming units. Search by SKU, name or barcode and filter by customer.</p>\n  <ul>\n    <li><span class=\"ui\">New product</span> creates a product on behalf of a customer, optionally with photos.</li>\n    <li>Open a product to see details, barcodes, stock by location, a photo gallery and the ledger of the latest 100 movements.</li>\n    <li><span class=\"ui\">Edit</span> changes name, size, weight, HS code, origin and active status. <span class=\"ui\">Add barcode</span> adds another code. <span class=\"ui\">Delete</span> works only for a product never used.</li>\n    <li>Photos: <span class=\"ui\">Add photos</span> (up to 4) and <span class=\"ui\">Remove</span>. The first is the thumbnail.</li>\n  </ul>\n  <div class=\"ex\"><b>Example</b><p>Marta scans a carton that has no barcode on file. She opens MUG-RED, clicks <span class=\"ui\">Add barcode</span>, scans it, and from then on scanning works.</p></div>\n</section>\n\n<section id=\"s-approvals\">\n  <h2>12. Approvals</h2>\n  <p class=\"lead\">Customers cannot edit or delete existing products and deliveries on their own. They send a request, and nothing changes until you approve it.</p>\n  <ol class=\"steps\">\n    <li>The overview card \"Changes to approve\" shows the count. Open <span class=\"ui\">Approvals</span>.</li>\n    <li>Click a request. You see the customer, the request and the <b>current value next to the requested one</b>.</li>\n    <li>Click <span class=\"ui\">Approve and apply</span> to make the change at once, or write a reason and click <span class=\"ui\">Decline</span>. The customer is emailed either way, and a decline reason is shown to them.</li>\n  </ol>\n  <div class=\"ex\"><b>Example: approve</b><p>Request \"Edit delivery IN-000012\" from Acme. The detail shows <i>Carrier: DSV → GLS</i> and <i>MUG-RED: 400 → 500</i>. Marta checks the dock plan, clicks <span class=\"ui\">Approve and apply</span>, and the delivery now shows 500. Anna gets an email.</p></div>\n  <div class=\"ex\"><b>Example: decline</b><p>Request \"Delete delivery IN-000009\". Marta sees the pallets are already on the dock, writes \"Goods arrived this morning, cannot be deleted\", and declines. Anna sees that reason on her delivery.</p></div>\n  <div class=\"rule\"><b>Rules</b><p>If a change can no longer be applied (for example the goods arrived after the request), approving it is refused and the request stays open. Decline it with a reason. A newer request for the same item replaces the older pending one. Staff themselves edit directly and never use this queue.</p></div>\n</section>\n\n<section id=\"s-scan\">\n  <h2>13. The scan app on a phone</h2>\n  <p class=\"lead\">Open <code>2ace.pl/scan</code> on a phone or handheld scanner. It works for Warehouse accounts, and for admins after the two-step check.</p>\n  <ol class=\"steps\">\n    <li>Sign in at <code>2ace.pl/login</code> with a Warehouse account, then open <code>/scan</code>. The first screen has <span class=\"ui\">Receive</span> and <span class=\"ui\">Put away</span>.</li>\n    <li>A hardware scanner types into the big box and presses Enter. On a phone, tap <span class=\"ui\">Camera</span>, or type the code and tap <span class=\"ui\">OK</span>.</li>\n  </ol>\n  <h3>Receive on the phone</h3>\n  <ol class=\"steps\">\n    <li>Tap <span class=\"ui\">Receive</span> and pick the delivery.</li>\n    <li>Scan or type the product barcode. A card shows the product photo, SKU and name so you can check it is the right item.</li>\n    <li>Set the quantity, then tap <span class=\"ui\">Good</span> or <span class=\"ui\">Damaged</span>. For damaged goods, take photos first.</li>\n    <li>The list below shows progress, for example <i>590 / 600 good · 10 damaged</i>. Tap <span class=\"ui\">Finish delivery</span> when done. If there are differences, the customer is emailed.</li>\n  </ol>\n  <h3>Put away on the phone</h3>\n  <ol class=\"steps\">\n    <li>Tap <span class=\"ui\">Put away</span> and scan the product.</li>\n    <li>The card shows how many are waiting in receiving. Check the quantity.</li>\n    <li>Scan the bin label, for example <code>A-01-01</code>. The move is posted, and the green message reads \"Moved 590 × MUG-BLUE to A-01-01\".</li>\n  </ol>\n  <div class=\"ex\"><b>Example</b><p>Marta scans <code>5901234123457</code>. The card shows the blue mug photo and \"590 waiting at R1\". She scans the label on the shelf, <code>A-01-01</code>, and hears the confirmation beep.</p></div>\n  <div class=\"note\"><b>Good to know</b><p>If you scan a wrong code, a red message tells you what was not found. A repeated scan cannot book stock twice.</p></div>\n</section>\n\n<section id=\"s-daily\">\n  <h2>14. A day in the warehouse</h2>\n  <p>Put the pieces together with one routine.</p>\n  <div class=\"tw\"><table>\n    <tr><th>When</th><th>Who</th><th>What</th></tr>\n    <tr><td>Start of day</td><td>Everyone</td><td>Open the overview. Work down the cards.</td></tr>\n    <tr><td>Morning</td><td>Support</td><td>Answer new requests. Register pending domains. Check customers past due.</td></tr>\n    <tr><td>As trucks arrive</td><td>Warehouse</td><td>Receive deliveries. Photograph damage. Close receiving.</td></tr>\n    <tr><td>After receiving</td><td>Warehouse</td><td>Put goods away. Resolve discrepancies.</td></tr>\n    <tr><td>Through the day</td><td>Warehouse or admin</td><td>Approve or decline customer change requests.</td></tr>\n    <tr><td>End of day</td><td>Admin</td><td>Check the audit log for anything unusual. Confirm nothing is left in \"To put away\".</td></tr>\n  </table></div>\n  <div class=\"ex\"><b>Example: Tuesday</b><p>08:30 two new requests, one asks for a quote, one is a billing question. 09:15 the DSV truck with IN-000012 arrives. 10:20 receiving is closed with two discrepancies and the customer is emailed. 10:40 goods are on shelf A-01-01. 14:00 Anna asks to change a unit count on a booked delivery and Marta approves it.</p></div>\n</section>\n</article></div></div><script>(function(){var toc=document.getElementById('toc'),links=document.getElementById('toclinks'),btn=document.getElementById('tocbtn');var secs=[].slice.call(document.querySelectorAll('article section'));secs.forEach(function(s){var h=s.querySelector('h2');if(!h)return;var a=document.createElement('a');a.href='#'+s.id;a.textContent=h.textContent;a.dataset.id=s.id;a.addEventListener('click',function(){toc.dataset.open='false'});links.appendChild(a)});btn.addEventListener('click',function(){toc.dataset.open=toc.dataset.open==='true'?'false':'true'});function spy(){var best=null;secs.forEach(function(s){if(s.getBoundingClientRect().top<140)best=s.id});[].forEach.call(links.querySelectorAll('a'),function(a){a.classList.toggle('on',a.dataset.id===best)})}window.addEventListener('scroll',spy,{passive:true});spy();\n// In-page links scroll instead of navigating. In the staff frame (built from inline text) a bare #link would resolve against the parent page and reload it inside the frame.\ndocument.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href^=\"#\"]');if(!a)return;var id=decodeURIComponent(a.getAttribute('href').slice(1));var t=id&&document.getElementById(id);if(!t)return;e.preventDefault();t.scrollIntoView();try{history.replaceState(null,'','#'+id)}catch(x){}});})();</script></body></html>";
export const OWNER_GUIDE = "<!DOCTYPE html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\"><title>Setup and maintenance</title><meta name=\"description\" content=\"For admins: how changes are published, which settings must exist and what to check when something looks wrong. Never paste secret values into chat or code.\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100,800&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap\" rel=\"stylesheet\"><style>/* Layout: a two-guide manual. Header with the audience switch, a sticky contents column, and long-form sections with worked examples. */\n  :root {\n    --bg: #F5F4F1; --surface: #FFFFFF; --fg: #14161A; --muted: #5C6068; --line: rgba(20,22,26,.13);\n    --accent: #B97A12; --accent-soft: rgba(227,154,43,.16); --ink: #0B0C0E; --on-ink: #F5F4F1;\n    --ok: #2F7D55; --ok-soft: rgba(47,125,85,.12); --warn: #8A5A10; --bad: #B3392C; --bad-soft: rgba(179,57,44,.1);\n    --ex-bg: #FBF3E3; --ex-line: #E39A2B;\n    --display: 'Archivo', 'Arial Narrow', Arial, sans-serif; --body: 'IBM Plex Sans', system-ui, sans-serif; --mono: 'IBM Plex Mono', ui-monospace, Menlo, monospace;\n  }\n  * { box-sizing: border-box; }\n  html { scroll-behavior: smooth; scroll-padding-top: 84px; }\n  body { margin: 0; padding-inline: 16px; background: var(--bg); color: var(--fg); font: 16px/1.65 var(--body); -webkit-font-smoothing: antialiased; }\n  a { color: var(--accent); }\n  .wrap { max-width: 1180px; margin-inline: auto; }\n\n  header.top { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; margin-inline: -16px; padding: 12px 16px; background: var(--ink); color: var(--on-ink); display: flex; flex-wrap: wrap; align-items: center; gap: 10px 20px; }\n  .brand { font-family: var(--display); font-variation-settings: 'wdth' 118; font-weight: 800; font-size: 22px; letter-spacing: .02em; }\n  .brand small { font: 500 11px var(--mono); letter-spacing: .16em; text-transform: uppercase; color: var(--accent); margin-left: 10px; }\n  .switch { display: flex; gap: 4px; margin-left: auto; padding: 3px; border: 1px solid rgba(245,244,241,.25); border-radius: 4px; }\n  .switch a { padding: 8px 14px; border-radius: 3px; color: rgba(245,244,241,.75); text-decoration: none; font: 500 12px var(--mono); letter-spacing: .1em; text-transform: uppercase; }\n  .switch a[aria-current=\"true\"] { background: var(--on-ink); color: var(--ink); }\n\n  .hero { padding-block: 40px 20px; }\n  .hero h1 { font-family: var(--display); font-variation-settings: 'wdth' 108; font-weight: 800; font-size: clamp(34px, 6vw, 60px); line-height: 1; letter-spacing: -.025em; margin: 0 0 14px; text-wrap: balance; }\n  .hero p { max-width: 64ch; color: var(--muted); margin: 0; font-size: 17px; }\n  .cast { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr)); gap: 12px; margin-top: 26px; }\n  .cast div { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 14px 16px; font-size: 14px; }\n  .cast b { display: block; font: 500 11px var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--accent); margin-bottom: 4px; }\n\n  .cols { display: grid; grid-template-columns: 250px minmax(0, 1fr); gap: 40px; padding-block: 24px 80px; align-items: start; }\n  nav.toc { position: sticky; top: calc(76px + env(safe-area-inset-top, 0px)); max-height: calc(100vh - 100px); overflow-y: auto; font-size: 14px; }\n  nav.toc h2 { font: 500 11px var(--mono); letter-spacing: .16em; text-transform: uppercase; color: var(--muted); margin: 0 0 10px; }\n  nav.toc a { display: block; padding: 6px 10px; border-left: 2px solid var(--line); color: var(--muted); text-decoration: none; }\n  nav.toc a:hover, nav.toc a.on { color: var(--fg); border-left-color: var(--accent); }\n  @media (max-width: 900px) { .cols { grid-template-columns: minmax(0, 1fr); gap: 8px; } nav.toc { position: static; max-height: none; } nav.toc .list { display: none; } nav.toc[data-open=\"true\"] .list { display: block; } .tocbtn { display: inline-block !important; } }\n  .tocbtn { display: none; font: 500 12px var(--mono); letter-spacing: .1em; text-transform: uppercase; background: var(--surface); color: var(--fg); border: 1px solid var(--line); border-radius: 4px; padding: 10px 14px; cursor: pointer; margin-bottom: 8px; }\n\n  article { min-width: 0; }\n  section { padding-block: 8px 28px; border-top: 1px solid var(--line); margin-top: 28px; }\n  section:first-of-type { border-top: 0; margin-top: 0; }\n  h2 { font-family: var(--display); font-variation-settings: 'wdth' 106; font-weight: 800; font-size: clamp(26px, 3.4vw, 36px); line-height: 1.08; letter-spacing: -.02em; margin: 18px 0 10px; text-wrap: balance; }\n  h3 { font-family: var(--display); font-weight: 800; font-size: 19px; letter-spacing: -.01em; margin: 26px 0 6px; }\n  p, li { max-width: 72ch; }\n  ol, ul { padding-left: 22px; } li { margin: 5px 0; }\n  .lead { color: var(--muted); font-size: 17px; }\n  code, .kbd { font-family: var(--mono); font-size: .88em; background: var(--accent-soft); padding: 1px 6px; border-radius: 3px; word-break: break-word; }\n\n  .ex { background: var(--ex-bg); border: 1px solid var(--line); border-left: 4px solid var(--ex-line); border-radius: 4px; padding: 14px 18px; margin: 16px 0; }\n  .ex > b:first-child, .note > b:first-child, .rule > b:first-child { display: block; font: 500 11px var(--mono); letter-spacing: .16em; text-transform: uppercase; margin-bottom: 6px; color: var(--accent); }\n  .note { background: var(--surface); border: 1px solid var(--line); border-radius: 4px; padding: 12px 18px; margin: 16px 0; font-size: 15px; }\n  .note > b:first-child { color: var(--muted); }\n  .rule { background: var(--bad-soft); border: 1px solid var(--line); border-radius: 4px; padding: 12px 18px; margin: 16px 0; font-size: 15px; }\n  .rule > b:first-child { color: var(--bad); }\n  .ex p, .note p, .rule p { margin: 6px 0; }\n  .steps { counter-reset: s; list-style: none; padding: 0; }\n  .steps > li { counter-increment: s; position: relative; padding: 4px 0 4px 44px; margin: 10px 0; }\n  .steps > li::before { content: counter(s); position: absolute; left: 0; top: 2px; width: 28px; height: 28px; border-radius: 50%; background: var(--ink); color: var(--on-ink); font: 500 13px/28px var(--mono); text-align: center; }\n  .tw { overflow-x: auto; margin: 14px 0; border: 1px solid var(--line); border-radius: 4px; background: var(--surface); }\n  table { border-collapse: collapse; width: 100%; font-size: 14px; min-width: 480px; }\n  th { text-align: left; font: 500 11px var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); padding: 10px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; }\n  td { padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; } tr:last-child td { border-bottom: 0; }\n  td.n, th.n { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }\n  .y { color: var(--ok); font-weight: 600; } .no { color: var(--muted); } .ro { color: var(--warn); }\n  .pill { display: inline-block; font: 500 11px var(--mono); letter-spacing: .06em; padding: 2px 8px; border-radius: 10px; background: var(--accent-soft); color: var(--fg); white-space: nowrap; }\n  .pill.ok { background: var(--ok-soft); color: var(--ok); } .pill.bad { background: var(--bad-soft); color: var(--bad); }\n  .ui { font-weight: 600; }\n  footer.end { border-top: 1px solid var(--line); padding-block: 24px 48px; color: var(--muted); font-size: 14px; }\n  [hidden] { display: none !important; }\n  @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }\n\n  body { padding-inline: 0; }\n  .wrap { padding-inline: 16px; }\n  header.top { margin-inline: 0; padding-inline: max(16px, calc((100vw - 1180px) / 2 + 16px)); }\n  .sitenav { margin-left: auto; display: flex; flex-wrap: wrap; gap: 6px 18px; }\n  .sitenav a { color: rgba(245,244,241,.8); text-decoration: none; font: 500 12px var(--mono); letter-spacing: .1em; text-transform: uppercase; }\n  .sitenav a:hover { color: var(--on-ink); }\n  a.brand { color: var(--on-ink); text-decoration: none; }\n  .legalline { border-top: 1px solid var(--line); padding-block: 22px 44px; color: var(--muted); font-size: 13px; }\n  .legalline a { margin-right: 16px; }\n</style></head><body><div class=\"wrap\"><div class=\"hero\" style=\"padding-block:24px 8px\"><h1 style=\"font-size:clamp(28px,4vw,42px)\">Setup and maintenance</h1><p>For admins: how changes are published, which settings must exist and what to check when something looks wrong. Never paste secret values into chat or code.</p></div><div class=\"cols\"><nav class=\"toc\" id=\"toc\" data-open=\"false\" aria-label=\"Contents\"><button class=\"tocbtn\" id=\"tocbtn\" type=\"button\">Contents</button><div class=\"list\"><h2 id=\"tochead\">Setup</h2><div id=\"toclinks\"></div></div></nav><article><section id=\"s-ops\">\n  <h2>1. Setup and maintenance</h2>\n  <p class=\"lead\">What keeps the platform running. Never paste secret values into chat or code. They live in Supabase and in a private <code>.env</code> file.</p>\n  <h3>Publishing changes</h3>\n  <ul>\n    <li><b>Website and admin pages</b>: pushing to GitHub <code>main</code> deploys to 2ace.pl by itself within about a minute. Hard-refresh (Cmd+Shift+R) to see changes.</li>\n    <li><b>Database</b>: <code>supabase db push --yes</code> applies new migrations. Do this before testing a new feature.</li>\n    <li><b>Server functions</b>: <code>supabase functions deploy &lt;names&gt; --use-api --project-ref &lt;project&gt;</code> publishes changed functions.</li>\n  </ul>\n  <h3>Settings that must exist</h3>\n  <div class=\"tw\"><table>\n    <tr><th>Setting</th><th>What it does</th></tr>\n    <tr><td><code>STRIPE_SECRET_KEY</code>, <code>STRIPE_WEBHOOK_SECRET</code></td><td>Payments, plan changes and the webhook that activates plans.</td></tr>\n    <tr><td><code>RESEND_API_KEY</code>, <code>EMAIL_FROM</code></td><td>Sending emails. The sending domain must be verified in Resend. Suggested sender: <code>2ACE &lt;hello@2ace.pl&gt;</code>.</td></tr>\n    <tr><td><code>LEAD_NOTIFY_TO</code></td><td>The team inbox for contact forms, requests, discrepancies and change requests: <code>hello@2ace.pl</code>.</td></tr>\n    <tr><td><code>SITE_URL</code></td><td>Links inside emails. <code>https://2ace.pl</code>.</td></tr>\n    <tr><td><code>HOSTINGER_API_TOKEN</code>, <code>HOSTINGER_AUTO_REGISTER</code>, <code>HOSTINGER_MAX_FIRST_YEAR_PLN</code>, <code>HOSTINGER_MONTHLY_CAP</code></td><td>Optional automatic domain registration with a price ceiling and monthly limit. Keep it off until you trust the manual queue.</td></tr>\n    <tr><td><code>STRIPE_AUTOMATIC_TAX</code></td><td>Turn on only after your VAT registration exists in Stripe.</td></tr>\n    <tr><td>Supabase Auth: Site URL <code>https://2ace.pl</code>, redirect URLs <code>https://2ace.pl/**</code>, <code>https://www.2ace.pl/**</code></td><td>Where confirmation and password links send people. A wrong value sends them to localhost.</td></tr>\n  </table></div>\n  <h3>When something looks wrong</h3>\n  <div class=\"tw\"><table>\n    <tr><th>Symptom</th><th>Likely cause and fix</th></tr>\n    <tr><td>Confirmation email links open localhost.</td><td>Supabase Auth Site URL is not set to https://2ace.pl.</td></tr>\n    <tr><td>Emails do not arrive.</td><td>Resend key missing, or the sending domain is not verified.</td></tr>\n    <tr><td>Customer paid but plan is not active.</td><td>The Stripe webhook is not reaching the server. Check the webhook endpoint and secret.</td></tr>\n    <tr><td>A plan change shows an \"ACTION NEEDED\" email.</td><td>Stripe and our plan record disagree. Compare the customer's Plan card with the Stripe subscription, and fix the one that is wrong.</td></tr>\n    <tr><td>Receiving photos or the customer change buttons fail.</td><td>The latest database migration or function deploy has not been run.</td></tr>\n    <tr><td>A staff member cannot see a screen.</td><td>Check their role. Admin and Support also need the two-step code.</td></tr>\n  </table></div>\n  <div class=\"ex\"><b>Example</b><p>You add a new feature with Claude and it asks you to run the database step. You run <code>supabase db push --yes</code>, then deploy the functions it names, then tell it to \"commit and push\". After about a minute you hard-refresh the admin panel and the new screen is there.</p></div>\n</section>\n</article></div></div><script>(function(){var toc=document.getElementById('toc'),links=document.getElementById('toclinks'),btn=document.getElementById('tocbtn');var secs=[].slice.call(document.querySelectorAll('article section'));secs.forEach(function(s){var h=s.querySelector('h2');if(!h)return;var a=document.createElement('a');a.href='#'+s.id;a.textContent=h.textContent;a.dataset.id=s.id;a.addEventListener('click',function(){toc.dataset.open='false'});links.appendChild(a)});btn.addEventListener('click',function(){toc.dataset.open=toc.dataset.open==='true'?'false':'true'});function spy(){var best=null;secs.forEach(function(s){if(s.getBoundingClientRect().top<140)best=s.id});[].forEach.call(links.querySelectorAll('a'),function(a){a.classList.toggle('on',a.dataset.id===best)})}window.addEventListener('scroll',spy,{passive:true});spy();\n// In-page links scroll instead of navigating. In the staff frame (built from inline text) a bare #link would resolve against the parent page and reload it inside the frame.\ndocument.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[href^=\"#\"]');if(!a)return;var id=decodeURIComponent(a.getAttribute('href').slice(1));var t=id&&document.getElementById(id);if(!t)return;e.preventDefault();t.scrollIntoView();try{history.replaceState(null,'','#'+id)}catch(x){}});})();</script></body></html>";
